<?php
session_start();require_once "../config/database.php";
if(!isset($_SESSION["user_id"])||$_SESSION["role"]!=="customer"){header("Location: ../auth/login.php");exit();}
$msg="";$err="";$tid="";
if($_SERVER["REQUEST_METHOD"]==="POST"){
$sender=trim($_POST["sender_name"]??"");$receiver=trim($_POST["receiver_name"]??"");$origin=trim($_POST["origin"]??"");$dest=trim($_POST["destination"]??"");$pkg=trim($_POST["package_type"]??"");$weight=(float)($_POST["weight"]??0);$priority=trim($_POST["priority"]??"Normal");
if($sender===""||$receiver===""||$origin===""||$dest===""||$pkg===""||$weight<=0)$err="Please fill all required fields.";
else{do{$tid="SL".date("Ymd").strtoupper(substr(str_shuffle("ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"),0,6));$c=$conn->prepare("SELECT id FROM shipments WHERE tracking_id=?");$c->bind_param("s",$tid);$c->execute();$exists=$c->get_result()->num_rows>0;$c->close();}while($exists);
$status="Booked";$s=$conn->prepare("INSERT INTO shipments(customer_id,tracking_id,sender_name,receiver_name,origin,destination,package_type,weight,priority,status) VALUES(?,?,?,?,?,?,?,?,?,?)");$s->bind_param("issssssdds",$_SESSION["user_id"],$tid,$sender,$receiver,$origin,$dest,$pkg,$weight,$priority,$status);
if($s->execute()){$shipid=$s->insert_id;$s->close();$e=$conn->prepare("INSERT INTO shipment_events(shipment_id,status,location,message) VALUES(?,?,?,?)");$em="Shipment successfully booked.";$e->bind_param("isss",$shipid,$status,$origin,$em);$e->execute();$e->close();$msg="Shipment created successfully! Tracking ID: ".$tid;}else{$err="Unable to create shipment: ".$conn->error;$s->close();}}
}
?>
