<div class="container"><div class="title"><h1>📦 Book New Shipment</h1><p>Create a new delivery.</p></div><div class="box"><?php if($msg):?><div class="success"><?=htmlspecialchars($msg)?><a href="track.php?tracking_id=<?=urlencode($tid)?>">📍 Track This Shipment</a></div><?php endif;?><?php if($err):?><div class="error"><?=htmlspecialchars($err)?></div><?php endif;?>
<form method="POST"><div class="grid"><div><label>Sender Name *</label><input name="sender_name" required></div><div><label>Receiver Name *</label><input name="receiver_name" required></div><div><label>Origin *</label><input name="origin" required></div><div><label>Destination *</label><input name="destination" required></div><div><label>Package Type *</label><select name="package_type" required><option value="">Select</option><option>Document</option><option>Electronics</option><option>Clothing</option><option>Food</option><option>Fragile</option><option>Other</option></select></div><div><label>Weight (kg) *</label><input type="number" name="weight" step=".01" min=".01" required></div><div class="full"><label>Priority</label><select name="priority"><option>Normal</option><option>Express</option><option>Urgent</option></select></div></div><button class="submit">🚚 BOOK SHIPMENT</button></form></div></div></body></html>